import{_ as l,C as n,o as d,c as i,j as e,a,b as s,w as o,E as A,a3 as c,a2 as E}from"./chunks/framework.DIWxYxwh.js";const _=JSON.parse('{"title":"RK3588 模型打包","description":"","frontmatter":{},"headers":[],"relativePath":"LLM推理/RK3588模型打包.md","filePath":"LLM推理/RK3588模型打包.md","lastUpdated":1791869861000}'),h={name:"LLM推理/RK3588模型打包.md"};function k(p,t,b,m,B,u){const r=n("Mermaid");return d(),i("div",null,[t[1]||(t[1]=e("h1",{id:"rk3588-模型打包",tabindex:"-1"},[a("RK3588 模型打包 "),e("a",{class:"header-anchor",href:"#rk3588-模型打包","aria-label":'Permalink to "RK3588 模型打包"'},"​")],-1)),t[2]||(t[2]=e("blockquote",null,[e("p",null,"RK3588 的板上不直接加载训练时的浮点权重：先在 PC 上把模型收成板端文件，板子再用运行时加载。语言模型和视觉编码器是两份产物、两条工具链，不能打进同一个文件。")],-1)),t[3]||(t[3]=e("h2",{id:"打包与加载流程",tabindex:"-1"},[a("打包与加载流程 "),e("a",{class:"header-anchor",href:"#打包与加载流程","aria-label":'Permalink to "打包与加载流程"'},"​")],-1)),(d(),s(c,null,{default:o(()=>[A(r,{id:"mermaid-11",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20PC%5B%22PC%20%E7%AB%AF%E8%BD%AC%E6%8D%A2%22%5D%0A%20%20%20%20%20%20%20%20LLM%5B%22%E8%AF%AD%E8%A8%80%E6%A8%A1%E5%9E%8B%3Cbr%2F%3ERKLLM-Toolkit%20%E2%86%92%20.rkllm%22%5D%0A%20%20%20%20%20%20%20%20VIS%5B%22%E8%A7%86%E8%A7%89%E7%BC%96%E7%A0%81%E5%99%A8%3Cbr%2F%3ERKNN%20%E5%B7%A5%E5%85%B7%20%E2%86%92%20.rknn%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20%E6%9D%BF%E7%AB%AF%5B%22RK3588%20%E5%8A%A0%E8%BD%BD%22%5D%0A%20%20%20%20%20%20%20%20R1%5B%22%E7%BA%AF%E6%96%87%E6%9C%AC%3Cbr%2F%3E%E5%8F%AA%E5%8A%A0%E8%BD%BD%20.rkllm%22%5D%0A%20%20%20%20%20%20%20%20R2%5B%22%E5%9B%BE%E6%96%87%3Cbr%2F%3E.rkllm%20%2B%20.rknn%22%5D%0A%20%20%20%20end%0A%20%20%20%20LLM%20--%3E%20R1%0A%20%20%20%20LLM%20--%3E%20R2%0A%20%20%20%20VIS%20--%3E%20R2%0A"})]),fallback:o(()=>[...t[0]||(t[0]=[a(" Loading... ",-1)])]),_:1})),t[4]||(t[4]=E('<h2 id="两份产物" tabindex="-1">两份产物 <a class="header-anchor" href="#两份产物" aria-label="Permalink to &quot;两份产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产物</th><th>工具链</th><th>职责</th><th>要点</th></tr></thead><tbody><tr><td><code>.rkllm</code></td><td>RKLLM-Toolkit，PC 上转换并量化</td><td>语言模型本身</td><td>常见 W8A8（权重 8 比特、激活按 8 比特）；也有 W4 一路，体积更小，精度和速度另测。优化级别取 0，运行时的优化路径才会打开——级别设错，板上每秒 token 会对不上按该级别测出的速度</td></tr><tr><td><code>.rknn</code></td><td>RKNN 运行时</td><td>视觉编码器：把图像变成语言模型能读的图像 token，不负责逐字生成</td><td>输入边长、精度写在这份编码器里；一张图变成多少图像 token 由分辨率和编码器决定，换边长或换模型，个数就变</td></tr></tbody></table><p>NPU 内核驱动负责和三核 NPU 打交道。驱动没装好或与运行时版本对不上，两份模型文件都在，程序仍然起不来。<strong>Toolkit、板端 Runtime、NPU 驱动要成套使用</strong>——只升级其中一层，加载时会在版本上对不上。</p><h2 id="纯文本和图文" tabindex="-1">纯文本和图文 <a class="header-anchor" href="#纯文本和图文" aria-label="Permalink to &quot;纯文本和图文&quot;">​</a></h2><ul><li><strong>纯文本</strong>只加载 <code>.rkllm</code>，提示从分词进入语言模型。视觉模型不占内存，也不占用 NPU 做编码。</li><li><strong>图文</strong>要同时加载 <code>.rknn</code>：图像先经过视觉模型得到一串图像 token，再和文本 token 拼在一起，交给语言模型做 prefill 和生成。拼进提示的特殊标记必须和这份语言模型的配置一致——以 Qwen3-VL 为例，图像段用 <code>&lt;|vision_start|&gt;</code> 和 <code>&lt;|vision_end|&gt;</code> 包住，图像内容占位是 <code>&lt;|image_pad|&gt;</code>。标记和训练时的约定不一致，模型仍会生成，图像 token 却对不上位置。</li></ul><p>有的模型还带音频编码器，同样是单独的一份 <code>.rknn</code>，用该模型自己的起止标记包住；不用这一路时，把音频文件和音频编码器的路径留空即可。</p><h2 id="运行参数不在权重里" tabindex="-1">运行参数不在权重里 <a class="header-anchor" href="#运行参数不在权重里" aria-label="Permalink to &quot;运行参数不在权重里&quot;">​</a></h2><p><code>.rkllm</code> 和 <code>.rknn</code> 里是权重和图。下面几项在每次启动时传入，改它们不用重新转换：</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td>上下文上限</td><td>提示、图像 token 和已生成的 token 都算在里面</td></tr><tr><td>单次生成上限</td><td>新 token 到达这个数，或模型写出结束符，生成停止</td></tr><tr><td>NPU 核数</td><td>设成 3 就是三核一起算</td></tr></tbody></table><p>进程要能找到 RKLLM Runtime 的动态库，一般是把库目录放进库搜索路径后再启动；找不到库时，失败发生在加载之前，和权重对不对无关。</p><blockquote><p>图文的顺序是固定的：视觉模型先编码，语言模型再 prefill、再生成。编码结果若留在进程里，下一句问同一张图就不必再编；每来一轮都重新编码，用户等到第一个字的时间要加上一整次编码。</p></blockquote>',11))])}const L=l(h,[["render",k]]);export{_ as __pageData,L as default};
